{
  "schema": "redline.threatmodel.v1",
  "issueKey": "EVAL-03",
  "sketch": {
    "components": ["Account settings page", "Email change endpoint", "Phone change endpoint", "Address change endpoint", "Session cookie handler", "Authentication service"],
    "dataStores": ["User profile database", "Session store"],
    "externalServices": [],
    "trustBoundaries": ["Browser-Server", "Frontend-Backend"],
    "dataClasses": ["pii", "credentials"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "ElevationOfPrivilege",
      "title": "Account takeover via email change without password confirmation",
      "scenario": "An attacker with temporary physical access to a user's unlocked computer or a stolen session cookie changes the account email to one they control. Without password re-entry required, they can immediately change the email, then use password reset to take over the account completely.",
      "component": "Email change endpoint",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "The change takes effect immediately without re-entering the password."
        }
      ],
      "asvs": ["V2.1.1", "V3.2.1"],
      "cwe": ["CWE-306"],
      "plainLanguage": "Someone who gets temporary access to your unlocked computer could change your email and lock you out of your account permanently.",
      "requirement": {
        "title": "Require password confirmation for email changes",
        "given": "a user is changing their account email",
        "when": "they submit the new email address",
        "then": "the system must require them to re-enter their current password before accepting the change"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Account hijacking via unverified email change",
      "scenario": "An attacker changes a victim's email to an address they control without the system verifying the new email. The legitimate user loses access and cannot recover their account since password reset emails go to the attacker's address.",
      "component": "Email change endpoint",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "The account settings page lets a logged-in user change their email address"
        },
        {
          "quote": "The change takes effect immediately"
        }
      ],
      "asvs": ["V2.1.12"],
      "cwe": ["CWE-640"],
      "plainLanguage": "An attacker could change your email to theirs without you getting a verification link, locking you out of your own account.",
      "requirement": {
        "title": "Verify new email before activation",
        "given": "a user submits a new email address",
        "when": "the email change is requested",
        "then": "the system must send a verification link to the new address and only activate it after the user clicks the link, keeping the old email active until then"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Extended window for session hijacking attacks",
      "scenario": "An attacker who steals a session cookie through XSS, network sniffing, or physical access can use it for up to 30 days to impersonate the victim, change their email, and take over the account. The long session lifetime dramatically increases the window of vulnerability.",
      "component": "Session cookie handler",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "Sessions are kept in a cookie for 30 days."
        }
      ],
      "asvs": ["V3.3.1", "V3.3.2"],
      "cwe": ["CWE-613"],
      "plainLanguage": "If someone steals your login cookie, they have a whole month to break into your account instead of hours or days.",
      "requirement": {
        "title": "Reduce session lifetime and require re-auth for sensitive changes",
        "given": "a user performs a sensitive operation like changing their email",
        "when": "their session is older than 15 minutes or they haven't recently authenticated",
        "then": "the system must require them to re-enter their password before proceeding"
      }
    },
    {
      "stride": "Tampering",
      "title": "Cross-site request forgery on account settings changes",
      "scenario": "An attacker crafts a malicious webpage that submits hidden requests to change the victim's email, phone, or address. When a logged-in user visits the page, their browser automatically sends their session cookie, and the account changes are made without their knowledge or consent.",
      "component": "Account settings page",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "The account settings page lets a logged-in user change their email address, phone number and shipping address."
        }
      ],
      "asvs": ["V4.2.2"],
      "cwe": ["CWE-352"],
      "plainLanguage": "An attacker could trick you into visiting a malicious website that secretly changes your account settings without you knowing.",
      "requirement": {
        "title": "Implement CSRF protection for all account changes",
        "given": "a form that changes account settings",
        "when": "it is submitted",
        "then": "the system must validate a unique, unguessable CSRF token that was generated for this user's session"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Session cookie vulnerable to theft via JavaScript or network interception",
      "scenario": "If the session cookie lacks HttpOnly and Secure flags, an XSS vulnerability elsewhere in the application could allow an attacker to steal it via JavaScript. Without the Secure flag, the cookie could also be intercepted over an unencrypted connection, enabling session hijacking.",
      "component": "Session cookie handler",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "Sessions are kept in a cookie"
        }
      ],
      "asvs": ["V3.4.2", "V3.4.1"],
      "cwe": ["CWE-614", "CWE-1004"],
      "plainLanguage": "Your login cookie could be stolen by malicious JavaScript or someone spying on your network connection if it's not properly protected.",
      "requirement": {
        "title": "Set security flags on session cookies",
        "given": "a session cookie is created",
        "when": "it is sent to the browser",
        "then": "it must have the HttpOnly flag (preventing JavaScript access) and Secure flag (requiring HTTPS) and SameSite=Strict or Lax"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No audit trail for account takeover investigation",
      "scenario": "When an attacker changes a user's email or other settings, there is no record of who made the change, when, or from which IP address. This makes it impossible to investigate account takeovers, detect compromised accounts, or provide evidence in disputes.",
      "component": "Account settings page",
      "likelihood": 2,
      "impact": 4,
      "evidence": [
        {
          "quote": "The account settings page lets a logged-in user change their email address, phone number and shipping address."
        }
      ],
      "asvs": ["V7.1.2", "V7.2.1"],
      "cwe": ["CWE-778"],
      "plainLanguage": "If someone breaks into your account and changes your settings, there's no record to help investigate what happened or prove it wasn't you.",
      "requirement": {
        "title": "Log all security-relevant account changes",
        "given": "a user changes their email, phone, or other account settings",
        "when": "the change is saved",
        "then": "the system must log the timestamp, IP address, user agent, old value, new value, and authenticated user ID in tamper-evident audit logs"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Account disruption via unlimited email changes",
      "scenario": "An attacker with access to a victim's account repeatedly changes the email address, flooding the new addresses with verification emails and making it difficult for the legitimate user to regain control. Without rate limiting, this can also be used to abuse the email sending service.",
      "component": "Email change endpoint",
      "likelihood": 2,
      "impact": 3,
      "evidence": [
        {
          "quote": "The change takes effect immediately"
        }
      ],
      "asvs": ["V4.2.1"],
      "cwe": ["CWE-770"],
      "plainLanguage": "An attacker could spam your account with email changes, making it hard to regain control and potentially getting your account flagged as abusive.",
      "requirement": {
        "title": "Rate limit account setting changes",
        "given": "a user attempts to change their email or phone number",
        "when": "they have already made changes in the past hour",
        "then": "the system must block further changes and return an error if more than 3 changes per hour are attempted"
      }
    }
  ]
}
